parameters.functionCode:
const sheetData = items.map(i => i.json);

// ambil intent dari node Parse Intent
const userIntent = $items("Parse Intent")[0].json.intent;

// cari berdasarkan intent (bukan keyword lagi)
const best = sheetData.find(d => d.intent === userIntent);

// 🔥 kalau tidak ditemukan
if (!best) {
  return [{
    message: userIntent,
    faq: "NOT_FOUND"
  }];
}

// format output
return [{
  message: userIntent,
  faq: `
Topik: ${best.question}

Jawaban:
${best.answer}

Link:
${best.url || "-"}
`
}];
